def bootstrap_means(rng: Lcg, sample: List[float], rounds: int) -> List[float]:
    """Means of `rounds` resamples (with replacement) of `sample`."""
    n = len(sample)
    means = []
    for _ in range(rounds):
        total = 0.0
        for _ in range(n):
            total += sample[rng.next_int(n)]
        means.append(total / n)
    return means
